import{_ as t,c as i,a2 as o,o as a}from"./chunks/framework.CKGreiRV.js";const p=JSON.parse('{"title":"Document Revision History","description":"","frontmatter":{},"headers":[],"relativePath":"resource/swift/revisionhistory.md","filePath":"resource/swift/revisionhistory.md","lastUpdated":1735910155000}'),n={name:"resource/swift/revisionhistory.md"};function r(s,e,l,d,c,h){return a(),i("div",null,e[0]||(e[0]=[o('<h1 id="document-revision-history" tabindex="-1">Document Revision History <a class="header-anchor" href="#document-revision-history" aria-label="Permalink to &quot;Document Revision History&quot;">​</a></h1><p>Review the recent changes to this book.</p><h2 id="_2024-09-16" tabindex="-1">2024-09-16 <a class="header-anchor" href="#_2024-09-16" aria-label="Permalink to &quot;2024-09-16&quot;">​</a></h2><ul><li>Updated for Swift 6.</li><li>Added the preconcurrency section with information about migrating to strict concurrency checking.</li><li>Added the Specifying the Error Type section with information about throwing errors of a specific type.</li><li>Updated the Macro-Expansion Expression section, now that any macro can be used as a default value for a parameter.</li><li>Added information about package-level access to the Access Control chapter.</li></ul><h2 id="_2024-03-05" tabindex="-1">2024-03-05 <a class="header-anchor" href="#_2024-03-05" aria-label="Permalink to &quot;2024-03-05&quot;">​</a></h2><ul><li>Updated for Swift 5.10.</li><li>Added information about nested protocols to the Delegation section.</li><li>Added deprecation information in the UIApplicationMain and NSApplicationMain sections.</li></ul><h2 id="_2023-12-11" tabindex="-1">2023-12-11 <a class="header-anchor" href="#_2023-12-11" aria-label="Permalink to &quot;2023-12-11&quot;">​</a></h2><ul><li>Updated for Swift 5.9.2.</li><li>Added information about the borrowing and consuming modifiers to the Parameter Modifiers section.</li><li>Added information in Declaring Constants and Variables about setting a constant’s value after its declaration.</li><li>Added more information about tasks, task groups, and task cancellation to the Concurrency chapter.</li><li>Added information in the Macros chapter about implementing macros in an existing Swift package.</li><li>Updated the attached section, now that extension macros have replaced conformance macros.</li><li>Added the backDeployed section with information about back deployment.</li></ul><h2 id="_2023-09-18" tabindex="-1">2023-09-18 <a class="header-anchor" href="#_2023-09-18" aria-label="Permalink to &quot;2023-09-18&quot;">​</a></h2><ul><li>Updated for Swift 5.9.</li><li>Added information about if and switch expressions to the Control Flow chapter and the Conditional Expression section.</li><li>Added the Macros chapter, with information about generating code at compile time.</li><li>Expanded the discussion of optionals in The Basics.</li><li>Added an example of concurrency to A Swift Tour.</li><li>Added information about boxed protocol types to the Opaque and Boxed Protocol Types chapter.</li><li>Added information about the buildPartialBlock(first:) and buildPartialBlock(accumulated:next:) methods to the Result Transformations section.</li><li>Added visionOS to the lists of platforms in available and Conditional Compilation Block.</li><li>Formatted the formal grammar to use blank lines for grouping.</li></ul><h2 id="_2023-03-30" tabindex="-1">2023-03-30 <a class="header-anchor" href="#_2023-03-30" aria-label="Permalink to &quot;2023-03-30&quot;">​</a></h2><ul><li>Updated for Swift 5.8.</li><li>Added the Deferred Actions section, showing defer outside of error handling.</li><li>Adopted Swift-DocC for publication.</li><li>Minor corrections and additions throughout.</li></ul><h2 id="_2022-09-12" tabindex="-1">2022-09-12 <a class="header-anchor" href="#_2022-09-12" aria-label="Permalink to &quot;2022-09-12&quot;">​</a></h2><ul><li>Updated for Swift 5.7.</li><li>Added the Sendable Types section, with information about sending data between actors and tasks, and added information about the @Sendable and @unchecked attributes to the Sendable and unchecked sections.</li><li>Added the Regular Expression Literals section with information about creating a regular expression.</li><li>Added information about the short form of if-let to the Optional Binding section.</li><li>Added information about #unavailable to the Checking API Availability section.</li></ul><h2 id="_2022-03-14" tabindex="-1">2022-03-14 <a class="header-anchor" href="#_2022-03-14" aria-label="Permalink to &quot;2022-03-14&quot;">​</a></h2><ul><li>Updated for Swift 5.6.</li><li>Updated the Explicit Member Expression section with information about using #if around chained method calls and other postfix expressions.</li><li>Updated the visual styling of figures throughout.</li></ul><h2 id="_2021-09-20" tabindex="-1">2021-09-20 <a class="header-anchor" href="#_2021-09-20" aria-label="Permalink to &quot;2021-09-20&quot;">​</a></h2><ul><li>Updated for Swift 5.5.</li><li>Added information about asynchronous functions, tasks, and actors to the Concurrency chapter, and to the Actor Declaration, Asynchronous Functions and Methods, and Await Operator sections.</li><li>Updated the Identifiers section with information about identifiers that start with an underscore.</li></ul><h2 id="_2021-04-26" tabindex="-1">2021-04-26 <a class="header-anchor" href="#_2021-04-26" aria-label="Permalink to &quot;2021-04-26&quot;">​</a></h2><ul><li>Updated for Swift 5.4.</li><li>Added the Result Builders and resultBuilder sections with information about result builders.</li><li>Added the Implicit Conversion to a Pointer Type section with information about how in-out parameters can be implicitly converted to unsafe pointers in a function call.</li><li>Updated the Variadic Parameters and Function Declaration sections, now that a function can have multiple variadic parameters.</li><li>Updated the Implicit Member Expression section, now that implicit member expressions can be chained together.</li></ul><h2 id="_2020-09-16" tabindex="-1">2020-09-16 <a class="header-anchor" href="#_2020-09-16" aria-label="Permalink to &quot;2020-09-16&quot;">​</a></h2><ul><li>Updated for Swift 5.3.</li><li>Added information about multiple trailing closures to the Trailing Closures section, and added information about how trailing closures are matched to parameters to the Function Call Expression section.</li><li>Added information about synthesized implementations of Comparable for enumerations to the Adopting a Protocol Using a Synthesized Implementation section.</li><li>Added the Contextual Where Clauses section now that you can write a generic where clause in more places.</li><li>Added the Unowned Optional References section with information about using unowned references with optional values.</li><li>Added information about the @main attribute to the main section.</li><li>Added #filePath to the Literal Expression section, and updated the discussion of #file.</li><li>Updated the Escaping Closures section, now that closures can refer to self implicitly in more scenarios.</li><li>Updated the Handling Errors Using Do-Catch and Do Statement sections, now that a catch clause can match against multiple errors.</li><li>Added more information about Any and moved it into the new Any Type section.</li><li>Updated the Property Observers section, now that lazy properties can have observers.</li><li>Updated the Protocol Declaration section, now that members of an enumeration can satisfy protocol requirements.</li><li>Updated the Stored Variable Observers and Property Observers section to describe when the getter is called before the observer.</li><li>Updated the Memory Safety chapter to mention atomic operations.</li></ul><h2 id="_2020-03-24" tabindex="-1">2020-03-24 <a class="header-anchor" href="#_2020-03-24" aria-label="Permalink to &quot;2020-03-24&quot;">​</a></h2><ul><li>Updated for Swift 5.2.</li><li>Added information about passing a key path instead of a closure to the Key-Path Expression section.</li><li>Added the Methods with Special Names section with information about syntactic sugar the lets instances of classes, structures, and enumerations be used with function call syntax.</li><li>Updated the Subscript Options section, now that subscripts support parameters with default values.</li><li>Updated the Self Type section, now that the Self can be used in more contexts.</li><li>Updated the Implicitly Unwrapped Optionals section to make it clearer that an implicitly unwrapped optional value can be used as either an optional or non-optional value.</li></ul><h2 id="_2019-09-10" tabindex="-1">2019-09-10 <a class="header-anchor" href="#_2019-09-10" aria-label="Permalink to &quot;2019-09-10&quot;">​</a></h2><ul><li>Updated for Swift 5.1.</li><li>Added information about functions that specify a protocol that their return value conforms to, instead of providing a specific named return type, to the Opaque and Boxed Protocol Types chapter.</li><li>Added information about property wrappers to the Property Wrappers section.</li><li>Added information about enumerations and structures that are frozen for library evolution to the frozen section.</li><li>Added the Functions With an Implicit Return and Shorthand Getter Declaration sections with information about functions that omit return.</li><li>Added information about using subscripts on types to the Type Subscripts section.</li><li>Updated the Enumeration Case Pattern section, now that an enumeration case pattern can match an optional value.</li><li>Updated the Memberwise Initializers for Structure Types section, now that memberwise initializers support omitting parameters for properties that have a default value.</li><li>Added information about dynamic members that are looked up by key path at runtime to the dynamicMemberLookup section.</li><li>Added macCatalyst to the list of target environments in Conditional Compilation Block.</li><li>Updated the Self Type section, now that Self can be used to refer to the type introduced by the current class, structure, or enumeration declaration.</li></ul><h2 id="_2019-03-25" tabindex="-1">2019-03-25 <a class="header-anchor" href="#_2019-03-25" aria-label="Permalink to &quot;2019-03-25&quot;">​</a></h2><ul><li>Updated for Swift 5.0.</li><li>Added the Extended String Delimiters section and updated the String Literals section with information about extended string delimiters.</li><li>Added the dynamicCallable section with information about dynamically calling instances as functions using the dynamicCallable attribute.</li><li>Added the unknown and Switching Over Future Enumeration Cases sections with information about handling future enumeration cases in switch statements using the unknown switch case attribute.</li><li>Added information about the identity key path (.self) to the Key-Path Expression section.</li><li>Added information about using the less than (&lt;) operator in platform conditions to the Conditional Compilation Block section.</li></ul><h2 id="_2018-09-17" tabindex="-1">2018-09-17 <a class="header-anchor" href="#_2018-09-17" aria-label="Permalink to &quot;2018-09-17&quot;">​</a></h2><ul><li>Updated for Swift 4.2.</li><li>Added information about accessing all of an enumeration’s cases to the Iterating over Enumeration Cases section.</li><li>Added information about #error and #warning to the Compile-Time Diagnostic Statement section.</li><li>Added information about inlining to the Declaration Attributes section under the inlinable and usableFromInline attributes.</li><li>Added information about members that are looked up by name at runtime to the Declaration Attributes section under the dynamicMemberLookup attribute.</li><li>Added information about the requires_stored_property_inits and warn_unqualified_access attributes to the Declaration Attributes section.</li><li>Added information about how to conditionally compile code depending on the Swift compiler version being used to the Conditional Compilation Block section.</li><li>Added information about #dsohandle to the Literal Expression section.</li></ul><h2 id="_2018-03-29" tabindex="-1">2018-03-29 <a class="header-anchor" href="#_2018-03-29" aria-label="Permalink to &quot;2018-03-29&quot;">​</a></h2><ul><li>Updated for Swift 4.1.</li><li>Added information about synthesized implementations of equivalence operators to the Equivalence Operators section.</li><li>Added information about conditional protocol conformance to the Extension Declaration section of the Declarations chapter, and to the Conditionally Conforming to a Protocol section of the Protocols chapter.</li><li>Added information about recursive protocol constraints to the Using a Protocol in Its Associated Type’s Constraints section.</li><li>Added information about the canImport() and targetEnvironment() platform conditions to Conditional Compilation Block.</li></ul><h2 id="_2017-12-04" tabindex="-1">2017-12-04 <a class="header-anchor" href="#_2017-12-04" aria-label="Permalink to &quot;2017-12-04&quot;">​</a></h2><ul><li>Updated for Swift 4.0.3.</li><li>Updated the Key-Path Expression section, now that key paths support subscript components.</li></ul><h2 id="_2017-09-19" tabindex="-1">2017-09-19 <a class="header-anchor" href="#_2017-09-19" aria-label="Permalink to &quot;2017-09-19&quot;">​</a></h2><ul><li>Updated for Swift 4.0.</li><li>Added information about exclusive access to memory to the Memory Safety chapter.</li><li>Added the Associated Types with a Generic Where Clause section, now that you can use generic where clauses to constrain associated types.</li><li>Added information about multiline string literals to the String Literals section of the Strings and Characters chapter, and to the String Literals section of the Lexical Structure chapter.</li><li>Updated the discussion of the objc attribute in Declaration Attributes, now that this attribute is inferred in fewer places.</li><li>Added the Generic Subscripts section, now that subscripts can be generic.</li><li>Updated the discussion in the Protocol Composition section of the Protocols chapter, and in the Protocol Composition Type section of the Types chapter, now that protocol composition types can contain a superclass requirement.</li><li>Updated the discussion of protocol extensions in Extension Declaration now that final isn’t allowed in them.</li><li>Added information about preconditions and fatal errors to the Assertions and Preconditions section.</li></ul><h2 id="_2017-03-27" tabindex="-1">2017-03-27 <a class="header-anchor" href="#_2017-03-27" aria-label="Permalink to &quot;2017-03-27&quot;">​</a></h2><ul><li>Updated for Swift 3.1.</li><li>Added the Extensions with a Generic Where Clause section with information about extensions that include requirements.</li><li>Added examples of iterating over a range to the For-In Loops section.</li><li>Added an example of failable numeric conversions to the Failable Initializers section.</li><li>Added information to the Declaration Attributes section about using the available attribute with a Swift language version.</li><li>Updated the discussion in the Function Type section to note that argument labels aren’t allowed when writing a function type.</li><li>Updated the discussion of Swift language version numbers in the Conditional Compilation Block section, now that an optional patch number is allowed.</li><li>Updated the discussion in the Function Type section, now that Swift distinguishes between functions that take multiple parameters and functions that take a single parameter of a tuple type.</li><li>Removed the Dynamic Type Expression section from the Expressions chapter, now that type(of:) is a Swift standard library function.</li></ul><h2 id="_2016-10-27" tabindex="-1">2016-10-27 <a class="header-anchor" href="#_2016-10-27" aria-label="Permalink to &quot;2016-10-27&quot;">​</a></h2><ul><li>Updated for Swift 3.0.1.</li><li>Updated the discussion of weak and unowned references in the Automatic Reference Counting chapter.</li><li>Added information about the unowned, unowned(safe), and unowned(unsafe) declaration modifiers in the Declaration Modifiers section.</li><li>Added a note to the Type Casting for Any and AnyObject section about using an optional value when a value of type Any is expected.</li><li>Updated the Expressions chapter to separate the discussion of parenthesized expressions and tuple expressions.</li></ul><h2 id="_2016-09-13" tabindex="-1">2016-09-13 <a class="header-anchor" href="#_2016-09-13" aria-label="Permalink to &quot;2016-09-13&quot;">​</a></h2><ul><li>Updated for Swift 3.0.</li><li>Updated the discussion of functions in the Functions chapter and the Function Declaration section to note that all parameters get an argument label by default.</li><li>Updated the discussion of operators in the Advanced Operators chapter, now that you implement them as type methods instead of as global functions.</li><li>Added information about the open and fileprivate access-level modifiers to the Access Control chapter.</li><li>Updated the discussion of inout in the Function Declaration section to note that it appears in front of a parameter’s type instead of in front of a parameter’s name.</li><li>Updated the discussion of the @noescape and @autoclosure attributes in the Escaping Closures and Autoclosures sections and the Attributes chapter now that they’re type attributes, rather than declaration attributes.</li><li>Added information about operator precedence groups to the Precedence for Custom Infix Operators section of the Advanced Operators chapter, and to the Precedence Group Declaration section of the Declarations chapter.</li><li>Updated discussion throughout to use macOS instead of OS X, Error instead of ErrorProtocol, and protocol names such as ExpressibleByStringLiteral instead of StringLiteralConvertible.</li><li>Updated the discussion in the Generic Where Clauses section of the Generics chapter and in the Generic Parameters and Arguments chapter, now that generic where clauses are written at the end of a declaration.</li><li>Updated the discussion in the Escaping Closures section, now that closures are nonescaping by default.</li><li>Updated the discussion in the Optional Binding section of the The Basics chapter and the While Statement section of the Statements chapter, now that if, while, and guard statements use a comma-separated list of conditions without where clauses.</li><li>Added information about switch cases that have multiple patterns to the Switch section of the Control Flow chapter and the Switch Statement section of the Statements chapter.</li><li>Updated the discussion of function types in the Function Type section now that function argument labels are no longer part of a function’s type.</li><li>Updated the discussion of protocol composition types in the Protocol Composition section of the Protocols chapter and in the Protocol Composition Type section of the Types chapter to use the new Protocol1 &amp; Protocol2 syntax.</li><li>Updated the discussion in the Dynamic Type Expression section to use the new type(of:) syntax for dynamic type expressions.</li><li>Updated the discussion of line control statements to use the #sourceLocation(file:line:) syntax in the Line Control Statement section.</li><li>Updated the discussion in Functions that Never Return to use the new Never type.</li><li>Added information about playground literals to the Literal Expression section.</li><li>Updated the discussion in the In-Out Parameters section to note that only nonescaping closures can capture in-out parameters.</li><li>Updated the discussion about default parameters in the Default Parameter Values section, now that they can’t be reordered in function calls.</li><li>Updated attribute arguments to use a colon in the Attributes chapter.</li><li>Added information about throwing an error inside the catch block of a rethrowing function to the Rethrowing Functions and Methods section.</li><li>Added information about accessing the selector of an Objective-C property’s getter or setter to the Selector Expression section.</li><li>Added information to the Type Alias Declaration section about generic type aliases and using type aliases inside of protocols.</li><li>Updated the discussion of function types in the Function Type section to note that parentheses around the parameter types are required.</li><li>Updated the Attributes chapter to note that the @IBAction, @IBOutlet, and @NSManaged attributes imply the @objc attribute.</li><li>Added information about the @GKInspectable attribute to the Declaration Attributes section.</li><li>Updated the discussion of optional protocol requirements in the Optional Protocol Requirements section to clarify that they’re used only in code that interoperates with Objective-C.</li><li>Removed the discussion of explicitly using let in function parameters from the Function Declaration section.</li><li>Removed the discussion of the Boolean protocol from the Statements chapter, now that the protocol has been removed from the Swift standard library.</li><li>Corrected the discussion of the @NSApplicationMain attribute in the Declaration Attributes section.</li></ul><h2 id="_2016-03-21" tabindex="-1">2016-03-21 <a class="header-anchor" href="#_2016-03-21" aria-label="Permalink to &quot;2016-03-21&quot;">​</a></h2><ul><li>Updated for Swift 2.2.</li><li>Added information about how to conditionally compile code depending on the version of Swift being used to the Conditional Compilation Block section.</li><li>Added information about how to distinguish between methods or initializers whose names differ only by the names of their arguments to the Explicit Member Expression section.</li><li>Added information about the #selector syntax for Objective-C selectors to the Selector Expression section.</li><li>Updated the discussion of associated types to use the associatedtype keyword in the Associated Types and Protocol Associated Type Declaration sections.</li><li>Updated information about initializers that return nil before the instance is fully initialized in the Failable Initializers section.</li><li>Added information about comparing tuples to the Comparison Operators section.</li><li>Added information about using keywords as external parameter names to the Keywords and Punctuation section.</li><li>Updated the discussion of the @objc attribute in the Declaration Attributes section to note that enumerations and enumeration cases can use this attribute.</li><li>Updated the Operators section with discussion of custom operators that contain a dot.</li><li>Added a note to the Rethrowing Functions and Methods section that rethrowing functions can’t directly throw errors.</li><li>Added a note to the Property Observers section about property observers being called when you pass a property as an in-out parameter.</li><li>Added a section about error handling to the A Swift Tour chapter.</li><li>Updated figures in the Weak References section to show the deallocation process more clearly.</li><li>Removed discussion of C-style for loops, the ++ prefix and postfix operators, and the -- prefix and postfix operators.</li><li>Removed discussion of variable function arguments and the special syntax for curried functions.</li></ul><h2 id="_2015-10-20" tabindex="-1">2015-10-20 <a class="header-anchor" href="#_2015-10-20" aria-label="Permalink to &quot;2015-10-20&quot;">​</a></h2><ul><li>Updated for Swift 2.1.</li><li>Updated the String Interpolation and String Literals sections now that string interpolations can contain string literals.</li><li>Added the Escaping Closures section with information about the @noescape attribute.</li><li>Updated the Declaration Attributes and Conditional Compilation Block sections with information about tvOS.</li><li>Added information about the behavior of in-out parameters to the In-Out Parameters section.</li><li>Added information to the Capture Lists section about how values specified in closure capture lists are captured.</li><li>Updated the Accessing Properties Through Optional Chaining section to clarify how assignment through optional chaining behaves.</li><li>Improved the discussion of autoclosures in the Autoclosures section.</li><li>Added an example that uses the ?? operator to the A Swift Tour chapter.</li></ul><h2 id="_2015-09-16" tabindex="-1">2015-09-16 <a class="header-anchor" href="#_2015-09-16" aria-label="Permalink to &quot;2015-09-16&quot;">​</a></h2><ul><li>Updated for Swift 2.0.</li><li>Added information about error handling to the Error Handling chapter, the Do Statement section, the Throw Statement section, the Defer Statement section, and the Try Operator section.</li><li>Updated the Representing and Throwing Errors section, now that all types can conform to the ErrorType protocol.</li><li>Added information about the new try? keyword to the Converting Errors to Optional Values section.</li><li>Added information about recursive enumerations to the Recursive Enumerations section of the Enumerations chapter and the Enumerations with Cases of Any Type section of the Declarations chapter.</li><li>Added information about API availability checking to the Checking API Availability section of the Control Flow chapter and the Availability Condition section of the Statements chapter.</li><li>Added information about the new guard statement to the Early Exit section of the Control Flow chapter and the Guard Statement section of the Statements chapter.</li><li>Added information about protocol extensions to the Protocol Extensions section of the Protocols chapter.</li><li>Added information about access control for unit testing to the Access Levels for Unit Test Targets section of the Access Control chapter.</li><li>Added information about the new optional pattern to the Optional Pattern section of the Patterns chapter.</li><li>Updated the Repeat-While section with information about the repeat-while loop.</li><li>Updated the Strings and Characters chapter, now that String no longer conforms to the CollectionType protocol from the Swift standard library.</li><li>Added information about the new Swift standard library print(_:separator:terminator) function to the Printing Constants and Variables section.</li><li>Added information about the behavior of enumeration cases with String raw values to the Implicitly Assigned Raw Values section of the Enumerations chapter and the Enumerations with Cases of a Raw-Value Type section of the Declarations chapter.</li><li>Added information about the @autoclosure attribute — including its @autoclosure(escaping) form — to the Autoclosures section.</li><li>Updated the Declaration Attributes section with information about the @available and @warn_unused_result attributes.</li><li>Updated the Type Attributes section with information about the @convention attribute.</li><li>Added an example of using multiple optional bindings with a where clause to the Optional Binding section.</li><li>Added information to the String Literals section about how concatenating string literals using the + operator happens at compile time.</li><li>Added information to the Metatype Type section about comparing metatype values and using them to construct instances with initializer expressions.</li><li>Added a note to the Debugging with Assertions section about when user-defined assertions are disabled.</li><li>Updated the discussion of the @NSManaged attribute in the Declaration Attributes section, now that the attribute can be applied to certain instance methods.</li><li>Updated the Variadic Parameters section, now that variadic parameters can be declared in any position in a function’s parameter list.</li><li>Added information to the Overriding a Failable Initializer section about how a nonfailable initializer can delegate up to a failable initializer by force-unwrapping the result of the superclass’s initializer.</li><li>Added information about using enumeration cases as functions to the Enumerations with Cases of Any Type section.</li><li>Added information about explicitly referencing an initializer to the Initializer Expression section.</li><li>Added information about build configuration and line control statements to the Compiler Control Statements section.</li><li>Added a note to the Metatype Type section about constructing class instances from metatype values.</li><li>Added a note to the Weak References section about weak references being unsuitable for caching.</li><li>Updated a note in the Type Properties section to mention that stored type properties are lazily initialized.</li><li>Updated the Capturing Values section to clarify how variables and constants are captured in closures.</li><li>Updated the Declaration Attributes section to describe when you can apply the @objc attribute to classes.</li><li>Added a note to the Handling Errors section about the performance of executing a throw statement. Added similar information about the do statement in the Do Statement section.</li><li>Updated the Type Properties section with information about stored and computed type properties for classes, structures, and enumerations.</li><li>Updated the Break Statement section with information about labeled break statements.</li><li>Updated a note in the Property Observers section to clarify the behavior of willSet and didSet observers.</li><li>Added a note to the Access Levels section with information about the scope of private access.</li><li>Added a note to the Weak References section about the differences in weak references between garbage collected systems and ARC.</li><li>Updated the Special Characters in String Literals section with a more precise definition of Unicode scalars.</li></ul><h2 id="_2015-04-08" tabindex="-1">2015-04-08 <a class="header-anchor" href="#_2015-04-08" aria-label="Permalink to &quot;2015-04-08&quot;">​</a></h2><ul><li>Updated for Swift 1.2.</li><li>Swift now has a native Set collection type. For more information, see Sets.</li><li>@autoclosure is now an attribute of the parameter declaration, not its type. There’s also a new @noescape parameter declaration attribute. For more information, see Declaration Attributes.</li><li>Type methods and properties now use the static keyword as a declaration modifier. For more information see Type Variable Properties.</li><li>Swift now includes the as? and as! failable downcast operators. For more information, see Checking for Protocol Conformance.</li><li>Added a new guide section about String Indices.</li><li>Removed the overflow division (&amp;/) and overflow remainder (&amp;%) operators from Overflow Operators.</li><li>Updated the rules for constant and constant property declaration and initialization. For more information, see Constant Declaration.</li><li>Updated the definition of Unicode scalars in string literals. See Special Characters in String Literals.</li><li>Updated Range Operators to note that a half-open range with the same start and end index will be empty.</li><li>Updated Closures Are Reference Types to clarify the capturing rules for variables.</li><li>Updated Value Overflow to clarify the overflow behavior of signed and unsigned integers</li><li>Updated Protocol Declaration to clarify protocol declaration scope and members.</li><li>Updated Defining a Capture List to clarify the syntax for weak and unowned references in closure capture lists.</li><li>Updated Operators to explicitly mention examples of supported characters for custom operators, such as those in the Mathematical Operators, Miscellaneous Symbols, and Dingbats Unicode blocks.</li><li>Constants can now be declared without being initialized in local function scope. They must have a set value before first use. For more information, see Constant Declaration.</li><li>In an initializer, constant properties can now only assign a value once. For more information, see Assigning Constant Properties During Initialization.</li><li>Multiple optional bindings can now appear in a single if statement as a comma-separated list of assignment expressions. For more information, see Optional Binding.</li><li>An Optional-Chaining Expression must appear within a postfix expression.</li><li>Protocol casts are no longer limited to @objc protocols.</li><li>Type casts that can fail at runtime now use the as? or as! operator, and type casts that are guaranteed not to fail use the as operator. For more information, see Type-Casting Operators.</li></ul><h2 id="_2014-10-16" tabindex="-1">2014-10-16 <a class="header-anchor" href="#_2014-10-16" aria-label="Permalink to &quot;2014-10-16&quot;">​</a></h2><ul><li>Updated for Swift 1.1.</li><li>Added a full guide to Failable Initializers.</li><li>Added a description of Failable Initializer Requirements for protocols.</li><li>Constants and variables of type Any can now contain function instances. Updated the example in Type Casting for Any and AnyObject to show how to check for and cast to a function type within a switch statement.</li><li>Enumerations with raw values now have a rawValue property rather than a toRaw() method and a failable initializer with a rawValue parameter rather than a fromRaw() method. For more information, see Raw Values and Enumerations with Cases of a Raw-Value Type.</li><li>Added a new reference section about Failable Initializers, which can trigger initialization failure.</li><li>Custom operators can now contain the ? character. Updated the Operators reference to describe the revised rules. Removed a duplicate description of the valid set of operator characters from Custom Operators.</li></ul><h2 id="_2014-08-18" tabindex="-1">2014-08-18 <a class="header-anchor" href="#_2014-08-18" aria-label="Permalink to &quot;2014-08-18&quot;">​</a></h2><ul><li>New document that describes Swift 1.0, Apple’s new programming language for building iOS and OS X apps.</li><li>Added a new section about Initializer Requirements in protocols.</li><li>Added a new section about Class-Only Protocols.</li><li>Assertions and Preconditions can now use string interpolation. Removed a note to the contrary.</li><li>Updated the Concatenating Strings and Characters section to reflect the fact that String and Character values can no longer be combined with the addition operator (+) or addition assignment operator (+=). These operators are now used only with String values. Use the String type’s append(_😃 method to append a single Character value onto the end of a string.</li><li>Added information about the availability attribute to the Declaration Attributes section.</li><li>Optionals no longer implicitly evaluate to true when they have a value and false when they do not, to avoid confusion when working with optional Bool values. Instead, make an explicit check against nil with the == or != operators to find out if an optional contains a value.</li><li>Swift now has a Nil-Coalescing Operator (a ?? b), which unwraps an optional’s value if it exists, or returns a default value if the optional is nil.</li><li>Updated and expanded the Comparing Strings section to reflect and demonstrate that string and character comparison and prefix / suffix comparison are now based on Unicode canonical equivalence of extended grapheme clusters.</li><li>You can now try to set a property’s value, assign to a subscript, or call a mutating method or operator through Optional Chaining. The information about Accessing Properties Through Optional Chaining has been updated accordingly, and the examples of checking for method call success in Calling Methods Through Optional Chaining have been expanded to show how to check for property setting success.</li><li>Added a new section about Accessing Subscripts of Optional Type through optional chaining.</li><li>Updated the Accessing and Modifying an Array section to note that you can no longer append a single item to an array with the += operator. Instead, use the append(_😃 method, or append a single-item array with the += operator.</li><li>Added a note that the start value a for the Range Operators a...b and a..&lt;b must not be greater than the end value b.</li><li>Rewrote the Inheritance chapter to remove its introductory coverage of initializer overrides. This chapter now focuses more on the addition of new functionality in a subclass, and the modification of existing functionality with overrides. The chapter’s example of Overriding Property Getters and Setters has been rewritten to show how to override a description property. (The examples of modifying an inherited property’s default value in a subclass initializer have been moved to the Initialization chapter.)</li><li>Updated the Initializer Inheritance and Overriding section to note that overrides of a designated initializer must now be marked with the override modifier.</li><li>Updated the Required Initializers section to note that the required modifier is now written before every subclass implementation of a required initializer, and that the requirements for required initializers can now be satisfied by automatically inherited initializers.</li><li>Infix Operator Methods no longer require the @infix attribute.</li><li>The @prefix and @postfix attributes for Prefix and Postfix Operators have been replaced by prefix and postfix declaration modifiers.</li><li>Added a note about the order in which Prefix and Postfix Operators are applied when both a prefix and a postfix operator are applied to the same operand.</li><li>Operator functions for Compound Assignment Operators no longer use the @assignment attribute when defining the function.</li><li>The order in which modifiers are specified when defining Custom Operators has changed. You now write prefix operator rather than operator prefix, for example.</li><li>Added information about the dynamic declaration modifier in Declaration Modifiers.</li><li>Added information about how type inference works with Literals.</li><li>Added more information about curried functions.</li><li>Added a new chapter about Access Control.</li><li>Updated the Strings and Characters chapter to reflect the fact that Swift’s Character type now represents a single Unicode extended grapheme cluster. Includes a new section on Extended Grapheme Clusters and more information about Unicode Scalar Values and Comparing Strings.</li><li>Updated the String Literals section to note that Unicode scalars inside string literals are now written as \\u{n}, where n is a hexadecimal number between 0 and 10FFFF, the range of Unicode’s codespace.</li><li>The NSString length property is now mapped onto Swift’s native String type as utf16Count, not utf16count.</li><li>Swift’s native String type no longer has an uppercaseString or lowercaseString property. The corresponding section in Strings and Characters has been removed, and various code examples have been updated.</li><li>Added a new section about Initializer Parameters Without Argument Labels.</li><li>Added a new section about Required Initializers.</li><li>Added a new section about Optional Tuple Return Types.</li><li>Updated the Type Annotations section to note that multiple related variables can be defined on a single line with one type annotation.</li><li>The @optional, @lazy, @final, and @required attributes are now the optional, lazy, final, and required Declaration Modifiers.</li><li>Updated the entire book to refer to ..&lt; as the Half-Open Range Operator (rather than the “half-closed range operator”).</li><li>Updated the Accessing and Modifying a Dictionary section to note that Dictionary now has a Boolean isEmpty property.</li><li>Clarified the full list of characters that can be used when defining Custom Operators.</li><li>nil and the Booleans true and false are now Literals.</li><li>Swift’s Array type now has full value semantics. Updated the information about Mutability of Collections and Arrays to reflect the new approach. Also clarified the assignment and copy behavior for strings arrays and dictionaries.</li><li>Array Type Shorthand Syntax is now written as [SomeType] rather than SomeType[].</li><li>Added a new section about Dictionary Type Shorthand Syntax, which is written as [KeyType: ValueType].</li><li>Added a new section about Hash Values for Set Types.</li><li>Examples of Closure Expressions now use the global sorted(<em>:</em>😃 function rather than the global sort(<em>:</em>😃 function, to reflect the new array value semantics.</li><li>Updated the information about Memberwise Initializers for Structure Types to clarify that the memberwise structure initializer is made available even if a structure’s stored properties don’t have default values.</li><li>Updated to ..&lt; rather than .. for the Half-Open Range Operator.</li><li>Added an example of Extending a Generic Type.</li></ul>',54)]))}const f=t(n,[["render",r]]);export{p as __pageData,f as default};
